            (t += String.fromCharCode(((31 & a) << 6) | (63 & n))),
            (e += 2))
          : ((n = r.charCodeAt(e + 1)),
            (o = r.charCodeAt(e + 2)),
            (t += String.fromCharCode(
              ((15 & a) << 12) | ((63 & n) << 6) | (63 & o)
            )),
            (e += 3));
      return t;
    })(d);
  })(
    (r = r
      .split('')
